CREATE    VIEW [FO].[vwSubsDDForecast]
AS
SELECT 
	[RecID]
	,[DataAreaID]
	,[AccountNum]
	,[TransDate]
	,[Voucher]
	,[Invoice]
	,[TXT]
	,[AmountCur]
	,[SettleAmountCur]
	,[AmountMST]
	,[SettleAmountMST]
	,[CurrencyCode]
	,[DueDate]
	,[Closed]
	--,[Dimension]
	--,[Dimension2_]
	--,[Dimension3_]
	,[ExchRate]
	,[ExchAdjustment]
	,[PaymMode]
	,[PaymReference]
	,[PaymMethod]
	--,[RicRecalculation]
	--,[RicRecalReference]
	--,[RicCustInterfaceRef]
	,[RicInvoiceType]
	,[OffsetRecID]
	--,[RicExternalInvoiceRef]
	,[LastSettleVoucher]
FROM [synapse_fo].[CUSTTRANS_RICS]
WHERE RicInvoiceType IN ('SUB','SUR','LHL')
  AND PaymMode = 'DD'
  AND YEAR(Closed) = 1900
